create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text,role text default 'sales' check(role in('admin','academy_manager','sales','finance','board')),created_at timestamptz default now());
create table if not exists courses(id uuid primary key default gen_random_uuid(),title text not null,university text,start_date date,capacity int not null default 0,price bigint not null default 0,status text default 'open',created_at timestamptz default now());
create table if not exists leads(id uuid primary key default gen_random_uuid(),full_name text not null,phone text not null,course_id uuid references courses(id) on delete set null,source text,status text default 'new' check(status in('new','contacted','interested','awaiting','paid','lost')),next_followup date,owner text,notes text,created_at timestamptz default now());
create table if not exists registrations(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete cascade,course_id uuid references courses(id) on delete cascade,status text default 'confirmed',created_at timestamptz default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete set null,course_id uuid references courses(id) on delete set null,amount bigint not null check(amount>=0),status text default 'pending' check(status in('pending','approved','rejected')),paid_at date,method text,reference_no text,receipt_url text,created_at timestamptz default now());
create table if not exists expenses(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id) on delete set null,category text not null,amount bigint not null check(amount>=0),date date,description text,created_at timestamptz default now());
create table if not exists activities(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete cascade,type text,description text,next_followup timestamptz,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists invoices(id uuid primary key default gen_random_uuid(),invoice_no text unique not null,lead_id uuid references leads(id),course_id uuid references courses(id),subtotal bigint default 0,discount bigint default 0,total bigint default 0,paid bigint default 0,status text default 'issued',issued_at date default current_date,created_at timestamptz default now());
alter table profiles enable row level security; alter table courses enable row level security; alter table leads enable row level security; alter table registrations enable row level security; alter table payments enable row level security; alter table expenses enable row level security; alter table activities enable row level security; alter table invoices enable row level security;
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$ select role from profiles where id=auth.uid() $$;
do $$ declare t text; begin foreach t in array array['profiles','courses','leads','registrations','payments','expenses','activities','invoices'] loop execute format('drop policy if exists authenticated_read on %I',t); execute format('create policy authenticated_read on %I for select to authenticated using (true)',t); end loop; end $$;
create policy manage_courses on courses for all to authenticated using (my_role() in ('admin','academy_manager')) with check (my_role() in ('admin','academy_manager'));
create policy manage_leads on leads for all to authenticated using (my_role() in ('admin','academy_manager','sales')) with check (my_role() in ('admin','academy_manager','sales'));
create policy manage_registrations on registrations for all to authenticated using (my_role() in ('admin','academy_manager','sales','finance')) with check (my_role() in ('admin','academy_manager','sales','finance'));
create policy manage_payments on payments for all to authenticated using (my_role() in ('admin','academy_manager','finance')) with check (my_role() in ('admin','academy_manager','finance'));
create policy manage_expenses on expenses for all to authenticated using (my_role() in ('admin','academy_manager','finance')) with check (my_role() in ('admin','academy_manager','finance'));
create policy manage_activities on activities for all to authenticated using (my_role() in ('admin','academy_manager','sales')) with check (my_role() in ('admin','academy_manager','sales'));
create policy manage_invoices on invoices for all to authenticated using (my_role() in ('admin','academy_manager','finance')) with check (my_role() in ('admin','academy_manager','finance'));
create policy own_profile on profiles for select to authenticated using(id=auth.uid() or my_role()='admin');
